message.content:
¿Puedes **crear** un clon de una aplicación de software popular?

Ejemplo (completo y reproducible) de cómo empezar a crear un “clon” sencillo de una app popular: un clon básico de **Notas** (tipo Apple Notes/Google Keep) como aplicación web con varios párrafos y código.

---

## 1) Descripción
Esta mini-app permite:
- Crear notas con **título** y **contenido**
- Listarlas
- Eliminar una nota
- Guardarlas en el navegador con `localStorage` (persisten al recargar)

---

## 2) Código (un solo archivo `index.html`)
Copia esto en un archivo llamado `index.html` y ábrelo en tu navegador:

```html
<!doctype html>
<html lang="es">
<head>
  <meta charset="utf-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1" />
  <title>Mini Notas (clon simple)</title>
  <style>
    body { font-family: system-ui, Arial, sans-serif; max-width: 900px; margin: 40px auto; padding: 0 16px; }
    h1 { margin-bottom: 6px; }
    .muted { color: #555; margin-top: 0; }
    .grid { display: grid; grid-template-columns: 1fr 1fr; gap: 16px; align-items: start; }
    label { display:block; font-weight: 600; margin: 10px 0 6px; }
    input, textarea { width: 100%; padding: 10px; box-sizing: border-box; }
    textarea { min-height: 160px; resize: vertical; }
    button { padding: 10px 12px; cursor: pointer; }
    .row { display:flex; gap: 10px; align-items:center; margin-top: 10px; }
    .card { border: 1px solid #ddd; border-radius: 10px; padding: 12px; }
    .note { border: 1px solid #e6e6e6; border-radius: 10px; padding: 12px; margin-bottom: 10px; }
    .note h3 { margin: 0 0 6px; }
    .note p { margin: 0; white-space: pre-wrap; }
    .note .meta { margin-top: 10px; display:flex; justify-content: space-between; align-items:center; }
    .note small { color:#666; }
  </style>
</head>
<body>
  <h1>Mini Notas</h1>
  <p class="muted">Clon básico estilo “app de notas”: crear, listar, borrar y persistir en el navegador.</p>

  <div class="grid">
    <section class="card">
      <h2>Nueva nota</h2>
      <label for="title">Título</label>
      <input id="title" placeholder="Ej. Ideas para el proyecto" />

      <label for="content">Contenido</label>
      <textarea id="content" placeholder="Escribe aquí..."></textarea>

      <div class="row">
        <button id="add">Guardar nota</button>
        <button id="clear">Limpiar</button>
      </div>
    </section>

    <section class="card">
      <h2>Mis notas</h2>
      <div id="list"></div>
    </section>
  </div>

  <script>
    const STORAGE_KEY = "mini-notas:v1";

    /** @type {{id:string,title:string,content:string,createdAt:number}[]} */
    let notes = load();

    const $title = document.getElementById("title");
    const $content = document.getElementById("content");
    const $list = document.getElementById("list");
    const $add = document.getElementById("add");
    const $clear = document.getElementById("clear");

    function uid() {
      return Math.random().toString(16).slice(2) + "-" + Date.now().toString(16);
    }

    function formatDate(ts) {
      return new Date(ts).toLocaleString();
    }

    function save() {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(notes));
    }

    function load() {
      try {
        const raw = localStorage.getItem(STORAGE_KEY);
        return raw ? JSON.parse(raw) : [];
      } catch {
        return [];
      }
    }

    function render() {
      if (!notes.length) {
        $list.innerHTML = "<p class='muted'>Aún no hay notas. Crea la primera.</p>";
        return;
      }

      $list.innerHTML = notes
        .slice()
        .sort((a, b) => b.createdAt - a.createdAt)
        .map(n => `
          <div class="note">
            <h3>${escapeHtml(n.title || "(Sin título)")}</h3>
            <p>${escapeHtml(n.content || "")}</p>
            <div class="meta">
              <small>${formatDate(n.createdAt)}</small>
              <button data-id="${n.id}">Eliminar</button>
            </div>
          </div>
        `).join("");

      $list.querySelectorAll("button[data-id]").forEach(btn => {
        btn.addEventListener("click", () => {
          const id = btn.getAttribute("data-id");
          notes = notes.filter(n => n.id !== id);
          save();
          render();
        });
      });
    }

    function escapeHtml(s) {
      return String(s)
        .replaceAll("&", "&amp;")
        .replaceAll("<", "&lt;")
        .replaceAll(">", "&gt;")
        .replaceAll('"', "&quot;")
        .replaceAll("'", "&#039;");
    }

    $add.addEventListener("click", () => {
      const title = $title.value.trim();
      const content = $content.value.trim();

      notes.push({ id: uid(), title, content, createdAt: Date.now() });
      save();
      render();

      $title.value = "";
      $content.value = "";
      $title.focus();
    });

    $clear.addEventListener("click", () => {
      $title.value = "";
      $content.value = "";
      $title.focus();
    });

    render();
  </script>
</body>
</html>
```

---

Si me dices **qué app popular** quieres clonar (p. ej., “Trello”, “Spotify”, “WhatsApp” pero en versión demo), te preparo un ejemplo igual de reproducible con las funciones mínimas y una arquitectura sugerida.
